/* arsenal/fonts/fonts.js · the shared font-loading contract for arsenal demos and patterns (moved here from
   patterns/morph-type/fonts). Generated: vendor WOFF2 -> TTF (fontTools) -> data URLs, so p.loadFont / FontFace work
   on file:// without fetch or the p5.woff2 add-on. Keys 'Family|weight'. window.MORPH_FONTS is kept as an alias. */
window.ARSENAL_FONTS=window.MORPH_FONTS={
 'Big Shoulders Display|600':'data:font/ttf;base64,',
 'IBM Plex Mono|400':'data:font/ttf;base64,',
 'Sofia Sans Extra Condensed|700':'data:font/ttf;base64,',
 'Space Mono|400':'data:font/ttf;base64,',
 'Jost|600':'data:font/ttf;base64,',
 'Red Hat Mono|400':'data:font/ttf;base64,',
};
